package io.knowledgebrain.knowledge;
import java.time.Clock;
import java.util.*;
import java.util.concurrent.*;
import org.flywaydb.core.Flyway;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.web.server.ResponseStatusException;
import static org.assertj.core.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_KNOWLEDGE_DATABASE_URL",matches=".+")
class ContributionIntegrationTest {
    JdbcTemplate jdbc;ConceptStore concepts;ContributionStore store;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,author,reviewer;String trace="f".repeat(32);
    @BeforeEach void setup(){var source=new PGSimpleDataSource();source.setURL(System.getenv("BRAIN_TEST_KNOWLEDGE_DATABASE_URL"));source.setUser("brain_knowledge");source.setPassword(System.getenv("BRAIN_TEST_KNOWLEDGE_DATABASE_PASSWORD"));Flyway.configure().dataSource(source).locations("classpath:db/migration").load().migrate();jdbc=new JdbcTemplate(source);concepts=new ConceptStore(source,Clock.systemUTC());store=new ContributionStore(source,concepts,Clock.systemUTC());space=ids.next();author=ids.next();reviewer=ids.next();}
    ContributionStore.Proposal submit(){return store.submit(space,author,null,0,"Public idea","Explicit text","New concept",trace);}
    @Test void approvalDoesNotPublishMergeCreatesOneCanonicalRevisionAndAtomicAudit(){var p=submit();assertThat(concepts.list(space,null,20).items()).isEmpty();p=store.decide(space,p.contributionId(),reviewer,1,"APPROVED","Checked",trace);assertThat(concepts.list(space,null,20).items()).isEmpty();p=store.merge(space,p.contributionId(),reviewer,2,trace);assertThat(p.state()).isEqualTo("MERGED");assertThat(p.mergedConceptVersion()).isEqualTo(1L);assertThat(concepts.get(space,p.conceptId()).visibility()).isEqualTo("PUBLIC");assertThat(store.reviews(space,p.contributionId())).extracting(ContributionStore.Review::decision).containsExactly("APPROVED","MERGED");assertThat(jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=? AND aggregatetype='contribution'",Long.class,p.contributionId())).isEqualTo(3);assertThat(concepts.history(space,p.conceptId(),Long.MAX_VALUE,10)).hasSize(1);}
    @Test void selfReviewSelfMergeAndDirectPrivateMutationAreDenied(){var p=submit();UUID id=p.contributionId();assertThatThrownBy(()->store.decide(space,id,author,1,"APPROVED","Self",trace)).isInstanceOf(ResponseStatusException.class).satisfies(e->assertThat(((ResponseStatusException)e).getStatusCode().value()).isEqualTo(403));store.decide(space,id,reviewer,1,"APPROVED","Checked",trace);assertThatThrownBy(()->store.merge(space,id,author,2,trace)).isInstanceOf(ResponseStatusException.class);var merged=store.merge(space,id,reviewer,2,trace);assertThatThrownBy(()->concepts.change(space,merged.conceptId(),author,1,"Bypass","",false,trace)).isInstanceOf(ResponseStatusException.class);assertThat(concepts.get(space,merged.conceptId()).version()).isEqualTo(1);}
    @Test void staleApprovedUpdateCannotOverwriteNewRevision(){var p=submit();store.decide(space,p.contributionId(),reviewer,1,"APPROVED","Checked",trace);store.merge(space,p.contributionId(),reviewer,2,trace);var a=store.submit(space,author,p.conceptId(),1,"Winner","","Update",trace);var b=store.submit(space,author,p.conceptId(),1,"Stale","","Update",trace);store.decide(space,a.contributionId(),reviewer,1,"APPROVED","Checked",trace);store.decide(space,b.contributionId(),reviewer,1,"APPROVED","Checked",trace);store.merge(space,a.contributionId(),reviewer,2,trace);assertThatThrownBy(()->store.merge(space,b.contributionId(),reviewer,2,trace)).isInstanceOf(ResponseStatusException.class).satisfies(e->assertThat(((ResponseStatusException)e).getStatusCode().value()).isEqualTo(412));assertThat(store.get(space,b.contributionId()).state()).isEqualTo("APPROVED");assertThat(store.reviews(space,b.contributionId())).hasSize(1);assertThat(concepts.get(space,p.conceptId()).title()).isEqualTo("Winner");}
    @Test void concurrentReviewHasOneWinnerAndRejectedProposalCannotMerge()throws Exception{var p=submit();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var start=new CountDownLatch(1);var jobs=new ArrayList<Future<Integer>>();for(int i=0;i<5;i++)jobs.add(pool.submit(()->{start.await();try{store.decide(space,p.contributionId(),reviewer,1,"REJECTED","Needs evidence",trace);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var results=new ArrayList<Integer>();for(var job:jobs)results.add(job.get(20,TimeUnit.SECONDS));assertThat(results).containsOnly(200,412);assertThat(Collections.frequency(results,200)).isEqualTo(1);}assertThat(store.reviews(space,p.contributionId())).hasSize(1);assertThatThrownBy(()->store.merge(space,p.contributionId(),reviewer,2,trace)).isInstanceOf(ResponseStatusException.class);assertThat(concepts.list(space,null,20).items()).isEmpty();}
    @Test void failedOutboxRollsBackCanonicalMergeReviewAndState(){var p=submit();store.decide(space,p.contributionId(),reviewer,1,"APPROVED","Checked",trace);jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT validation_contribution_merge CHECK(type <> 'ContributionMerged') NOT VALID");try{assertThatThrownBy(()->store.merge(space,p.contributionId(),reviewer,2,trace)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(store.get(space,p.contributionId()).state()).isEqualTo("APPROVED");assertThat(store.reviews(space,p.contributionId())).hasSize(1);assertThat(concepts.list(space,null,20).items()).isEmpty();assertThat(jdbc.queryForObject("SELECT count(*) FROM concept_revision WHERE concept_id=?",Long.class,p.conceptId())).isZero();}finally{jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT validation_contribution_merge");}}
    @Test void privateTargetAndOtherSpaceCannotBePublishedOrRead(){var privateConcept=concepts.create(space,author,"Private","secret",trace);assertThatThrownBy(()->store.submit(space,author,privateConcept.conceptId(),1,"Expose","secret","Copy",trace)).isInstanceOf(ResponseStatusException.class);var p=submit();assertThatThrownBy(()->store.get(ids.next(),p.contributionId())).isInstanceOf(ResponseStatusException.class);assertThat(store.list(ids.next(),null,20).items()).isEmpty();assertThat(concepts.get(space,privateConcept.conceptId()).visibility()).isEqualTo("PRIVATE");}
    @Test void keysetSummariesStayBoundedEvenWithMaximumEscapedDescriptions(){for(int i=0;i<3;i++)store.submit(space,author,null,0,"Bounded "+i,"\u0001".repeat(32768),"Explicit text",trace);var first=store.list(space,null,2);assertThat(first.items()).hasSize(2);assertThat(first.nextAfter()).isNotNull();assertThat(tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(first).getBytes(java.nio.charset.StandardCharsets.UTF_8).length).isLessThan(1000);assertThat(store.list(space,first.nextAfter(),2).items()).hasSize(1);assertThat(store.list(space,first.nextAfter(),2).nextAfter()).isNull();}
}
